    // and the result node has end_of_word == true.
    const char *words[] = {"hello"};
    struct trie *root = helper_build_trie(words, 1);
    TEST_ASSERT_NOT_NULL(root);

    // Test: Check if the inserted word is contained.
    // Path 2 conditions: trie_search returns 0 (success) and result is not NULL,
    // and result->end_of_word is true, so trie_contains should return 1.
    int result = trie_contains(root, "hello", 5);

    // Assertions
    TEST_ASSERT_EQUAL_INT(1, result);

    // Cleanup
    trie_free(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_trie_contains_word_found_and_is_end_of_word);
    return UNITY_END();
}

